// Already validated and projected onto this task's fields by "Normalize Input".
const variables = $input.first().json.variables;
const chunkSize = 20;

const measureLines = [
  'Scale',
  'Definition: Numeric values where magnitude and the distance between values are meaningful (interval or ratio).',
  'Cues: age in years, income, hours, counts, amounts, durations, percentages, weights, factor scores, indices, dates stored as numbers.',
  '',
  'Ordinal',
  'Definition: Categories with an intrinsic order, but the distance between adjacent categories is not meaningful.',
  'Cues: Likert agreement scales, satisfaction ratings, education level, ISCED, frequency bands (never/sometimes/often), income brackets, deciles, left-right placement 0-10, self-rated health.',
  '',
  'Nominal',
  'Definition: Categories with no intrinsic order.',
  'Cues: sex, country, region code, occupation code, marital status, yes/no flags, party voted for, identifiers, free-text strings, interviewer id.'
];

const measureContext = measureLines.join('\n');

const systemPrompt = 'You are a metadata classification assistant that assigns the SPSS Measure (level of measurement) to survey variables.\n\nThe Measure is a property of how the values of the variable relate to each other. Every variable carries exactly one of these three levels:\n\n' + measureContext + '\n\nFor each variable, return the single measurement level that applies.\n- Use every field given for a variable together: variable_name, variable_label, variable_description, variable_source_question, variable_datatype, variable_format, variable_value_labels (at most the first 15 value/label pairs; variable_value_labels_total is the full count) and variable_missing_values. A missing field means it is unknown.\n- A variable whose values carry substantive labels for each code is categorical: choose Ordinal if the categories form a ranked sequence, otherwise Nominal.\n- A 0-10 or 1-7 rating with labelled endpoints only (e.g. 0 = not at all, 10 = completely) is Ordinal, not Scale.\n- Numeric quantities with a unit (years, hours, NOK, persons, percent) are Scale even when a few codes such as 777/888/999 are reserved for missing values.\n- Identifiers, ids, serial numbers, string variables, and open-text answers are Nominal.\n- Binary yes/no or dummy 0/1 variables are Nominal.\n- Weights, sampling fractions and derived indices are Scale.\n- Do not answer with more than one level and do not invent a level outside the list.\n- Return exactly one entry per variable, echoing variable_name unchanged.';

const chunks = [];
for (let i = 0; i < variables.length; i += chunkSize) {
  chunks.push(variables.slice(i, i + chunkSize));
}

return chunks.map(chunk => ({
  json: {
    systemPrompt,
    userMessage: JSON.stringify(chunk, null, 2)
  }
}));

